<template>
  <Layout>
    <WorkflowShell :flow-id="String(route.params.flowId)" :project-id="String(route.params.projectId)" title="Release" subtitle="Catalogue-driven release configuration" active="configuration">
      <template #actions><Button label="Save" :disabled="!flow" @click="save" /><Button label="Ship" :disabled="!flow" @click="ship" /></template>
      <Message v-if="error" severity="error">{{ error }}</Message>
      <section v-if="flow" class="release-editor">
        <label>Name <InputText v-model="flow.name" /></label>
        <label>Source <Select v-model="flow.source.provider" :options="catalog.sources" optionLabel="label" optionValue="id" /></label>
        <label v-for="field in sourceDefinition(flow.source.provider)?.fields || []" :key="field.key">{{ field.label }} <Select v-if="field.type === 'select' || field.type === 'connection'" :model-value="fieldValue(flow.source.config, field.key)" :options="fieldOptions('source', field)" optionLabel="label" optionValue="value" @update:model-value="setField(flow.source.config, field.key, $event)" /><InputText v-else :type="field.type === 'password' ? 'password' : 'text'" :model-value="fieldValue(flow.source.config, field.key)" @update:model-value="setField(flow.source.config, field.key, $event)" @blur="inspectSource" /></label>
        <h3>Build</h3><div class="catalog-grid"><button v-for="provider in catalog.producers" :key="provider.id" :class="{ selected: flow.producers.some((item) => item.provider === provider.id) }" @click="toggleProducer(provider.id)">{{ provider.label }}</button></div>
        <div v-for="producer in flow.producers" :key="producer.id" class="release-provider">
          <strong>{{ producerDefinition(producer.provider)?.label || producer.provider }}</strong>
          <label>Input <Select :model-value="artifactRefValue(producer.input || { source: true })" :options="producerInputs(producer)" optionLabel="label" optionValue="value" @update:model-value="setProducerInput(producer, $event)" /></label>
          <label v-for="field in producerDefinition(producer.provider)?.fields || []" :key="field.key">{{ field.label }} <Select v-if="field.type === 'select' || field.type === 'connection'" :model-value="fieldValue(producer.config, field.key)" :options="fieldOptions(`producer:${producer.id}`, field)" optionLabel="label" optionValue="value" @update:model-value="setField(producer.config, field.key, $event)" /><InputText v-else :type="field.type === 'password' ? 'password' : 'text'" :model-value="fieldValue(producer.config, field.key)" @update:model-value="setField(producer.config, field.key, $event)" /></label>
          <label v-for="target in catalog.producers.find((item) => item.id === producer.provider)?.targets || []" :key="target.id"><input type="checkbox" :checked="producer.targets.some((item) => item.id === target.id && item.enabled)" @change="toggleTarget(producer, target.id, ($event.target as HTMLInputElement).checked)" /> {{ target.label }}</label>
          <div v-for="target in producer.targets.filter((item) => item.enabled)" :key="`${producer.id}-${target.id}`"><label v-for="field in targetDefinition(producer.provider, target.id)?.fields || []" :key="field.key">{{ field.label }} <Select v-if="field.type === 'select' || field.type === 'connection'" :model-value="fieldValue(target.config, field.key)" :options="fieldOptions(`target:${producer.id}:${target.id}`, field)" optionLabel="label" optionValue="value" @update:model-value="setTargetField(target.config, field.key, $event)" /><InputText v-else :model-value="fieldValue(target.config, field.key)" @update:model-value="setTargetField(target.config, field.key, $event)" /></label></div>
        </div>
        <h3>Deploy</h3><div class="catalog-grid"><button v-for="provider in catalog.destinations" :key="provider.id" :class="{ selected: flow.destinations.some((item) => item.provider === provider.id) }" @click="toggleDestination(provider.id)">{{ provider.label }}</button></div>
        <div v-for="destination in flow.destinations" :key="destination.id" class="release-provider">
          <strong>{{ destinationDefinition(destination.provider)?.label || destination.provider }}</strong>
          <label v-for="field in destinationDefinition(destination.provider)?.fields || []" :key="field.key">{{ field.label }} <Select v-if="field.type === 'select' || field.type === 'connection'" :model-value="fieldValue(destination.config, field.key)" :options="fieldOptions(`destination:${destination.id}`, field)" optionLabel="label" optionValue="value" @update:model-value="setField(destination.config, field.key, $event)" /><InputText v-else :type="field.type === 'password' ? 'password' : 'text'" :model-value="fieldValue(destination.config, field.key)" @update:model-value="setField(destination.config, field.key, $event)" /></label>
          <Button label="Add slot" size="small" text @click="addSlot(destination)" />
          <div v-for="slot in destination.slots" :key="slot.id" class="release-slot">
            <Select :model-value="slotArtifactValue(slot)" :options="compatibleArtifacts(destination.provider)" optionLabel="label" optionValue="value" placeholder="Select artifact" @update:model-value="setSlotArtifact(slot, $event)" />
            <label v-for="field in destinationDefinition(destination.provider)?.slotFields || []" :key="field.key">{{ field.label }} <Select v-if="field.type === 'select' || field.type === 'connection'" :model-value="fieldValue(slot.config, field.key)" :options="fieldOptions(`slot:${destination.id}:${slot.id}`, field)" optionLabel="label" optionValue="value" @update:model-value="setField(slot.config, field.key, $event)" /><InputText v-else :model-value="fieldValue(slot.config, field.key)" @update:model-value="setField(slot.config, field.key, $event)" /></label>
            <Button icon="pi pi-trash" severity="danger" text @click="removeSlot(destination, slot.id)" />
          </div>
        </div>
        <Message v-if="issues.length" severity="warn"><ul><li v-for="issue in issues" :key="issue.code + issue.path">{{ issue.message }}</li></ul></Message>
      </section>
    </WorkflowShell>
  </Layout>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useRoute } from "vue-router";
import Button from "primevue/button";
import InputText from "primevue/inputtext";
import Select from "primevue/select";
import Message from "primevue/message";
import { applyArtifactDescriptorTransform, matchesArtifact, type ArtifactRef, type ReleaseCatalog, type ReleaseConfig, type ReleaseDestinationConfig, type ReleaseFieldDefinition, type ReleaseProducerConfig, type ReleaseDestinationSlot, type ValidationIssue } from "@pipelab/shared";
import { useAPI } from "../composables/api";
import { useConnectionsStore } from "../store/connections";
const route = useRoute(); const api = useAPI();
const catalog = ref<ReleaseCatalog>({ sources: [], producers: [], destinations: [] }); const flow = ref<ReleaseConfig>(); const issues = ref<ValidationIssue[]>([]); const error = ref(""); const inspectionOptions = ref<Record<string, Array<{ label: string; value: string }>>>({}); const connectionsStore = useConnectionsStore();
const sourceDefinition = (id: string) => catalog.value.sources.find((item) => item.id === id);
const producerDefinition = (id: string) => catalog.value.producers.find((item) => item.id === id);
const targetDefinition = (provider: string, id: string) => producerDefinition(provider)?.targets.find((item) => item.id === id);
const destinationDefinition = (id: string) => catalog.value.destinations.find((item) => item.id === id);
const fieldValue = (config: Record<string, unknown>, key: string) => String(config[key] ?? "");
const setField = (config: Record<string, unknown>, key: string, value: unknown) => { config[key] = String(value ?? ""); };
const setTargetField = (config: Record<string, unknown>, key: string, value: unknown) => { setField(config, key, value); };
const connectionOptions = (field: ReleaseFieldDefinition) => (connectionsStore.connections?.connections || []).filter((connection) => !field.integration || connection.pluginName === field.integration || connection.integrationName === field.integration).map((connection) => ({ label: connection.name || connection.id, value: connection.id }));
const fieldOptions = (scope: string, field: ReleaseFieldDefinition) => field.type === "connection" ? connectionOptions(field) : inspectionOptions.value[`${scope}.${field.key}`] || inspectionOptions.value[field.key] || field.options || [];
const applyInspection = (result: { issues?: ValidationIssue[]; fieldOptions?: Record<string, Array<{ label: string; value: string }>>; fieldValues?: Record<string, unknown> }) => { inspectionOptions.value = { ...inspectionOptions.value, ...(result.fieldOptions || {}) }; if (flow.value) for (const [key, value] of Object.entries(result.fieldValues || {})) { const [scope, field] = key.split("."); if (scope === "source") flow.value.source.config[field] = value; } issues.value = result.issues || []; };
const inspectProducer = async (producer: ReleaseProducerConfig) => { const result = await api.execute("release:producer:inspect", { provider: producer.provider, config: producer }); if (result.type === "success") applyInspection(result.result as { issues?: ValidationIssue[]; fieldOptions?: Record<string, Array<{ label: string; value: string }>>; fieldValues?: Record<string, unknown> }); };
const producedArtifacts = computed(() => { const source = flow.value ? sourceDefinition(flow.value.source.provider) : undefined; const result: Array<{ value: string; label: string; ref: ArtifactRef; descriptor: NonNullable<ReturnType<typeof sourceDefinition>>["output"] }> = []; if (source) result.push({ value: "source", label: `Source — ${source.label}`, ref: { source: true }, descriptor: source.output }); const pending = [...(flow.value?.producers || [])]; while (pending.length) { const index = pending.findIndex((producer) => result.some((artifact) => artifact.value === artifactRefValue(producer.input || { source: true }))); if (index < 0) break; const producer = pending.splice(index, 1)[0]; const input = result.find((artifact) => artifact.value === artifactRefValue(producer.input || { source: true })); for (const target of producer.targets.filter((item) => item.enabled)) { const definition = targetDefinition(producer.provider, target.id); const descriptor = definition?.output || (input && definition?.transform ? applyArtifactDescriptorTransform(input.descriptor, definition.transform) : undefined); if (descriptor) result.push({ value: `${producer.id}:${target.id}`, label: `${producerDefinition(producer.provider)?.label || producer.provider} — ${target.label || target.id}`, ref: { producerId: producer.id, outputId: target.id }, descriptor }); } } return result; });
const compatibleArtifacts = (provider: string) => producedArtifacts.value.filter((artifact) => matchesArtifact(artifact.descriptor, destinationDefinition(provider)?.accepts || {}));
const artifactRefValue = (ref: ArtifactRef) => "source" in ref ? "source" : `${ref.producerId}:${ref.outputId}`;
const slotArtifactValue = (slot: ReleaseDestinationSlot) => artifactRefValue(slot.input);
const setSlotArtifact = (slot: ReleaseDestinationSlot, value: string) => { const artifact = producedArtifacts.value.find((item) => item.value === value); if (artifact) slot.input = artifact.ref; };
const producerInputs = (producer: ReleaseProducerConfig) => producedArtifacts.value.filter((artifact) => artifact.value !== producer.id && matchesArtifact(artifact.descriptor, producerDefinition(producer.provider)?.accepts || {})).map((artifact) => ({ value: artifact.value, label: artifact.label }));
const setProducerInput = (producer: ReleaseProducerConfig, value: string) => { const artifact = producedArtifacts.value.find((item) => item.value === value); if (artifact) producer.input = artifact.ref; };
const inspectSource = async () => { if (!flow.value || !flow.value.source.provider) return; const result = await api.execute("release:source:inspect", { provider: flow.value.source.provider, config: flow.value.source.config }); if (result.type === "success") applyInspection(result.result as { issues?: ValidationIssue[]; fieldOptions?: Record<string, Array<{ label: string; value: string }>>; fieldValues?: Record<string, unknown> }); };
onMounted(async () => { await connectionsStore.init(); const [catalogResult, flowResult] = await Promise.all([api.execute("release:catalog:get"), api.execute("workflow:load-by-name", { name: `workflows/${route.params.flowId}` })]); if (catalogResult.type === "success") catalog.value = catalogResult.result; if (flowResult.type === "success") { flow.value = flowResult.result as ReleaseConfig; await inspectSource(); } else error.value = flowResult.ipcError; });
const toggleProducer = (provider: string) => { if (!flow.value) return; const index = flow.value.producers.findIndex((item) => item.provider === provider); if (index >= 0) flow.value.producers.splice(index, 1); else { const definition = catalog.value.producers.find((item) => item.id === provider); flow.value.producers.push({ id: provider.split("/").pop() || provider, provider, enabled: true, input: { source: true }, targets: (definition?.targets || []).map((target, targetIndex) => ({ id: target.id, enabled: targetIndex === 0, config: { ...target.defaultConfig } })), config: { ...(definition?.defaultConfig || {}) } }); } };
const toggleTarget = (producer: ReleaseConfig["producers"][number], targetId: string, enabled: boolean) => { const target = producer.targets.find((item) => item.id === targetId); if (target) target.enabled = enabled; else { const definition = catalog.value.producers.find((item) => item.id === producer.provider)?.targets.find((item) => item.id === targetId); producer.targets.push({ id: targetId, enabled, config: { ...(definition?.defaultConfig || {}) } }); } void inspectProducer(producer); };
const toggleDestination = (provider: string) => { if (!flow.value) return; const index = flow.value.destinations.findIndex((item) => item.provider === provider); if (index >= 0) flow.value.destinations.splice(index, 1); else { const definition = catalog.value.destinations.find((item) => item.id === provider); flow.value.destinations.push({ id: provider.split("/").pop() || provider, provider, enabled: true, config: { ...(definition?.defaultConfig || {}) }, slots: [] }); } };
const addSlot = (destination: ReleaseDestinationConfig) => { const artifacts = compatibleArtifacts(destination.provider); if (!artifacts.length) return; destination.slots.push({ id: `${destination.id}-${destination.slots.length + 1}`, enabled: true, input: artifacts[0].ref, config: {} }); };
const removeSlot = (destination: ReleaseDestinationConfig, slotId: string) => { destination.slots = destination.slots.filter((slot) => slot.id !== slotId); };
const save = async () => { if (!flow.value) return; const result = await api.execute("workflow:save-by-name", { name: `workflows/${route.params.flowId}`, data: JSON.stringify(flow.value) }); if (result.type === "error") error.value = result.ipcError; };
const ship = async () => { if (!flow.value) return; error.value = ""; const validation = await api.execute("release:validate", { config: flow.value }); if (validation.type === "error") { error.value = validation.ipcError; return; } issues.value = validation.result.issues; if (issues.value.some((issue) => issue.severity === "error")) return; const saved = await api.execute("workflow:save-by-name", { name: `workflows/${route.params.flowId}`, data: JSON.stringify(flow.value) }); if (saved.type === "error") { error.value = saved.ipcError; return; } const result = await api.execute("workflow:execute", { name: `workflows/${route.params.flowId}`, release: { version: "0.0.0", description: flow.value.description || "" } }); if (result.type === "error") error.value = result.ipcError; };
</script>
